const toClaims=(rows,classification)=>rows.map(([id,claim,source_ids])=>({id,claim,source_ids,classification,status:'verified'}));

function materialize({area,foundation,sections,concepts,sources,claims,slugParts}){
  const dir=`${PACKAGE}/foundation_texts/${area.id}`;
  const moduleFiles=slugParts.map((slug,i)=>`${dir}/0${i+1}-${slug}.json`);
  for(let i=0;i<3;i++){
    const moduleSections=sections.slice(i*2,i*2+2);
    write(moduleFiles[i],{schema:'history_go_literature_foundation_module_v1',qualityProfile:'full_depth_v2',id:`${area.id}-${i+1}`,title:slugParts[i].split('-').map(x=>x[0].toUpperCase()+x.slice(1)).join(' '),sections:moduleSections,workedExamples:moduleSections.map(s=>({title:`Prøv modellen: ${s.title.replace(/^\d+\.\s*/,'')}`,object:foundation.topics.find(t=>t.id===s.coverageTopic).example,steps:['Avgrens tekstversjon, teoribegrep og analyseenhet.','Registrer minst tre teksttrekk før teoretisk forklaring.','Prøv hovedhypotesen mot en alternativ formell eller historisk forklaring.','Angi hvilket tilleggsmateriale som kreves for påstander om personer, institusjoner eller lesere.'],claimIds:s.paragraphClaimIds.flat().slice(0,3)})),commonMisconceptions:[{claim:'Teorien avslører automatisk det teksten egentlig betyr.',correction:'Begrepene formulerer hypoteser som må støttes av tekststeder, kilder, alternativer og inferensgrenser.'},{claim:'En litterær figur kan diagnostiseres som en virkelig person.',correction:'Tekstanalyse beskriver en litterær konstruksjon; kliniske slutninger krever helt andre data og etiske vilkår.'}]});
  }
  const conceptFile=`${dir}/concepts.json`,claimsFile=`${dir}/claims.json`;
  write(conceptFile,{schema:'history_go_literature_concept_registry_v1',version:'1.0.0',subject_id:'litteratur',coverage_area_id:area.id,status:'canonical_full_depth_concepts',concepts});
  write(claimsFile,{schema:'history_go_fagverk_claims_v1',version:'1.0.0',subject_id:'litteratur',chapter_id:area.id,verified_at:'2026-08-07',verification_status:'verified',sources,claims});
  const wrapper=`${PACKAGE}/foundation_texts/${area.id}.json`;
  write(wrapper,{schema:'history_go_literature_foundation_chapter_v1',version:'1.0.0',qualityProfile:'full_depth_v2',subject:'litteratur',id:area.id,title:area.title,subtitle:area.id.startsWith('post')?'Tegn, tekst, diskurs og ansvar':'Ubevisste konflikter, levd erfaring og situert frihet',lead:foundation.synthesis,coverage_topics:area.topics,learningObjectives:['skille teoritradisjoner og deres evidenskrav','operasjonalisere begreper i lokaliserbare tekstobservasjoner','analysere navngitte verk med konkurrerende hypoteser','unngå kliniske og historiske overinferenser','koble påstander til presise kilder','formulere etisk ansvar og inferensgrense'],moduleFiles,conceptRegistry:conceptFile,claimsFile,editorial_status:'foundation_text_ready',completion_note:'Alle seks kontraktstemaer er materialisert som full-dybde-artikler med begreper, navngitte verk, alternative forklaringer og påstandsspor.'});
  return wrapper;
}

const wrappers=[
  materialize({area:areas[0],foundation:foundations[0],sections:postSections,concepts:postConcepts,sources:postSources,claims:toClaims(postClaimTexts,'poststrukturalistisk_teori'),slugParts:['tegn-og-differanse','dekonstruksjon-og-diskurs','intertekst-og-ansvar']}),
  materialize({area:areas[1],foundation:foundations[1],sections:psychSections,concepts:psychConcepts,sources:psychSources,claims:toClaims(psychClaimTexts,'psykoanalyse_fenomenologi'),slugParts:['ubevisst-og-begjaer','relasjon-og-erfaring','eksistens-og-etikk']})
];

const coverageFile=`${PACKAGE}/coverage_contract_v1.json`,coverage=read(coverageFile);
coverage.coverage_areas=coverage.coverage_areas.filter(row=>!areas.some(area=>area.id===row.id));
let formalismIndex=coverage.coverage_areas.findIndex(row=>row.id==='formalisme_nykritikk_strukturalisme_semiotikk');
coverage.coverage_areas.splice(formalismIndex+1,0,areas[0]);
let hermIndex=coverage.coverage_areas.findIndex(row=>row.id==='hermeneutikk_fortolkning_teori');
coverage.coverage_areas.splice(hermIndex+1,0,areas[1]);
coverage.completion_definition.required_area_count=coverage.coverage_areas.length;
coverage.completion_definition.required_topic_count=coverage.coverage_areas.reduce((n,row)=>n+row.topics.length,0);
const completeAreas=coverage.coverage_areas.filter(row=>row.status==='chapter_and_overview_text_materialized');
coverage.progress={areas_total:coverage.coverage_areas.length,areas_with_foundation_text:coverage.coverage_areas.length,areas_complete:completeAreas.length,topics_total:coverage.completion_definition.required_topic_count,topics_with_foundation_text:coverage.completion_definition.required_topic_count,topics_complete:completeAreas.reduce((n,row)=>n+row.topics.length,0),honest_status:'Alle 27 områder og 162 temaer har særskrevet oversiktstekst. Fem områder og 30 temaer har full kapitteldybde, definerte begreper, navngitte analyseobjekter og påstandsspor; 22 områder og 132 temaer trenger fortsatt tilsvarende full-dybde-materialisering.'};
write(coverageFile,coverage);

const topicsFile=`${PACKAGE}/topic_foundations_v1.json`,topics=read(topicsFile);
topics.areas=topics.areas.filter(row=>!areas.some(area=>area.id===row.id));topics.areas.push(...foundations);
const topicById=new Map(topics.areas.map(row=>[row.id,row]));topics.areas=coverage.coverage_areas.map(row=>topicById.get(row.id));write(topicsFile,topics);

const indexFile=`${PACKAGE}/index.json`,index=read(indexFile);
index.files.foundation_chapters=[...new Set([...index.files.foundation_chapters,...wrappers.map(file=>file.replace(`${PACKAGE}/`,''))])];
let moduleCount=0,conceptCount=0,sourceCount=0,claimCount=0,fullDepth=0;
for(const file of index.files.foundation_chapters){const chapter=read(`${PACKAGE}/${file}`);moduleCount+=chapter.moduleFiles.length;const registry=read(chapter.conceptRegistry),claims=read(chapter.claimsFile);conceptCount+=registry.concepts.length;sourceCount+=claims.sources.length;claimCount+=claims.claims.length;if(chapter.qualityProfile==='full_depth_v2')fullDepth++;}
index.summary={coverage_area_count:coverage.coverage_areas.length,required_topic_count:coverage.completion_definition.required_topic_count,area_synthesis_count:topics.areas.length,topic_foundation_text_count:topics.areas.flatMap(row=>row.topics).length,materialized_foundation_chapter_count:index.files.foundation_chapters.length,materialized_module_count:moduleCount,defined_concept_count:conceptCount,verified_source_count:sourceCount,verified_claim_count:claimCount,completion_status:'critical_theory_core_expanded_22_areas_pending_full_depth'};
index.release_rule=`Pakken kan ikke merkes complete før alle ${coverage.coverage_areas.length} dekningsområder har fullverdige emneartikler, definerte begreper, navngitte verk eller objekter, påstandsspor og syntesekapittel. Nye dokumenterte fagfelt skal legges til kontrakten i stedet for å presses inn i overlastede områder.`;
write(indexFile,index);
console.log(`Materialiserte poststrukturalisme og psykoanalyse/fenomenologi: ${coverage.coverage_areas.length} områder / ${coverage.completion_definition.required_topic_count} temaer.`);
